package test;
import org.eclipse.jdt.core.IClassFile;
import org.eclipse.jdt.core.IPackageFragment;
// Assume JavaModelUtil exists for compilation
// public class JavaModelUtil { public static final String PACKAGE_INFO_CLASS = "package-info.class"; }
// Assume IPackageFragment is an interface with methods like getClassFile(String) and exists()

public class Example {
    public void foo(IPackageFragment pack) throws Exception {
        String PACKAGE_INFO_CLASS = "package-info.class"; // Placeholder constant
        IClassFile classFile = pack.getClassFile(PACKAGE_INFO_CLASS);
        if (classFile != null && classFile.exists()) {
            System.out.println("Found class file: " + classFile.getElementName());
        }
    }
}

