negativeExample:
package test;
import org.eclipse.jdt.core.IClassFile;
import org.eclipse.jdt.core.IPackageFragment;
// Assume JavaModelUtil exists for compilation

public class NegativeExample {
    public void foo(IPackageFragment pack) throws Exception {
        String PACKAGE_INFO_CLASS = "package-info.class";
        // Not a variable declaration, and assigned to a generic Object
        Object someFile = pack.getClassFile(PACKAGE_INFO_CLASS);
        if (someFile instanceof IClassFile && ((IClassFile)someFile).exists()) {
            System.out.println(((IClassFile)someFile).getElementName());
        }
        // Method call not part of a declaration to IClassFile
        pack.getClassFile("another-file.class");
    }
}
